from sympy import *
from sympy.printing.str import StrPrinter
from sympy.printing.precedence import precedence

printer = StrPrinter()

A = MatrixSymbol('A', 2, 2)
B = MatrixSymbol('B', 2, 2)
C = MatrixSymbol('C', 2, 2)

def fixed_print_MatMul(expr):
    from sympy import S
    coeff, matrices = expr.as_coeff_matrices()
    if coeff < 0:
        if coeff == -1:
            sign = '-'
            args = matrices
        else:
            sign = '-'
            args = [-coeff] + matrices
    else:
        sign = ''
        if coeff == 1:
            args = matrices
        else:
            args = [coeff] + matrices

    if not args:
        return sign + '1'

    result = '*'.join([printer.parenthesize(arg, precedence(expr)) for arg in args])
    return sign + result

def fixed_print_MatAdd(expr):
    terms = list(expr.args)
    PREC = precedence(expr)
    l = []
    for term in terms:
        if hasattr(term, 'as_coeff_matrices'):
            t = fixed_print_MatMul(term)
        else:
            t = printer._print(term)

        if t.startswith('-'):
            sign = '-'
            t = t[1:]
        else:
            sign = '+'

        if precedence(term) < PREC:
            l.extend([sign, '(%s)' % t])
        else:
            l.extend([sign, t])

    sign = l.pop(0)
    if sign == '+':
        sign = ''
    return sign + ' '.join(l)

# Test cases
test_cases = [
    A - B,
    A - A*B - B,
    A + B,
    A + B - C,
    A - 2*B,
    2*A - B,
    -A + B,
    -A - B,
    A + 2*B,
    -2*A + 3*B,
]

for expr in test_cases:
    result = fixed_print_MatAdd(expr)
    print(f'{expr:30s} -> {result}')
""}

